mapper.select:
SELECT COUNT(1)
FROM exp_bid
WHERE bid_code = #{bidCode}

    AND bid_id != #{excludeBidId}

SELECT b.bid_id AS bidId, b.tender_id AS tenderId, t.tender_name AS tenderName, b.supplier_id AS supplierId, b.bid_code AS bidCode, b.bid_name AS bidName, b.bid_total_amount AS bidTotalAmount, b.currency AS currency, b.bid_submit_time AS bidSubmitTime, b.bid_status AS bidStatus, b.win_flag AS winFlag, b.win_notice_no AS winNoticeNo, b.project_id AS projectId, b.org_id AS orgId, b.principal_person_id AS managerPersonId, b.salesman_person_id AS salesmanId, b.created_by AS createdBy, b.created_time AS createdTime FROM exp_bid b LEFT JOIN exp_tender t ON b.tender_id = t.tender_id
AND t.company_id IN
#{id}
AND 1 = 0
AND t.tender_name LIKE CONCAT('%', #{req.tenderName}, '%')
AND b.bid_code LIKE CONCAT('%', #{req.bidCode}, '%')
AND b.bid_name LIKE CONCAT('%', #{req.bidName}, '%')
AND b.bid_status = #{req.bidStatus}
AND b.win_flag = #{req.winFlag}
AND b.project_id IN
#{id}
AND 1 = 0
AND b.bid_submit_time >= #{req.bidSubmitTimeStart}
AND b.bid_submit_time <= #{req.bidSubmitTimeEnd}
AND b.created_by = #{req.createdBy}
AND b.created_time >= #{req.createdTimeStart}
AND b.created_time <= #{req.createdTimeEnd}
ORDER BY b.created_time DESC

SELECT COUNT(1)
FROM exp_bid
WHERE tender_id = #{tenderId}
AND supplier_id = #{supplierId}

    AND bid_id != #{excludeBidId}
